import java.util.*;

public class Main {
    public static List<Integer> solve(int n, int[] p, int[] q) {
        // 记录每个数字在 p 和 q 中的位置（下标从 1 开始）
        int[] posP = new int[n + 1];
        int[] posQ = new int[n + 1];

        for (int i = 0; i < n; i++) {
            posP[p[i]] = i + 1;
            posQ[q[i]] = i + 1;
        }

        List<Integer> ans = new ArrayList<>();
        int i = 1, j = 1; // 当前在两个排列中允许选择的最早位置

        // 从大到小扫描，贪心选择当前还能选的最大数字
        for (int x = n; x >= 1; x--) {
            if (posP[x] >= i && posQ[x] >= j) {
                ans.add(x);
                // 更新后续可选位置
                i = posP[x] + 1;
                j = posQ[x] + 1;
            }
        }

        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int[] p = new int[n];
        int[] q = new int[n];

        for (int i = 0; i < n; i++) {
            p[i] = sc.nextInt();
        }
        for (int i = 0; i < n; i++) {
            q[i] = sc.nextInt();
        }

        List<Integer> ans = solve(n, p, q);

        System.out.println(ans.size());
        for (int i = 0; i < ans.size(); i++) {
            if (i > 0) System.out.print(" ");
            System.out.print(ans.get(i));
        }
        System.out.println();

        sc.close();
    }
}
